-- Schema migrations as generated by Rails, Alembic, Flyway and hand-written
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, name TEXT, role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('member', 'admin')), settings JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users (id) ON DELETE CASCADE, total_cents INTEGER NOT NULL CHECK (total_cents >= 0), status TEXT NOT NULL DEFAULT 'pending', created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (order_id BIGINT NOT NULL, line_no INT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL DEFAULT 1, PRIMARY KEY (order_id, line_no), CONSTRAINT fk_order FOREIGN KEY (order_id) REFERENCES orders (id) ON UPDATE CASCADE ON DELETE RESTRICT, CONSTRAINT qty_positive CHECK (quantity > 0));
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sku text UNIQUE NOT NULL, price numeric(12, 2) NOT NULL, tags text[] DEFAULT '{}', dims int[][], attrs jsonb, search tsvector GENERATED ALWAYS AS (to_tsvector('english', coalesce(sku, ''))) STORED);
CREATE TEMP TABLE tmp_ids (id bigint) ON COMMIT DROP;
CREATE UNLOGGED TABLE staging_events (payload jsonb, received_at timestamptz DEFAULT now());
CREATE TABLE audit_log (LIKE users INCLUDING ALL);
CREATE TABLE new_orders AS SELECT * FROM orders WHERE created_at > now() - interval '30 days';
CREATE TABLE measurements (city_id int NOT NULL, logdate date NOT NULL, peaktemp int, unitsales int) PARTITION BY RANGE (logdate);
CREATE TABLE measurements_y2024m01 PARTITION OF measurements FOR VALUES FROM ('2024-01-01') TO ('2024-02-01');
CREATE TABLE measurements_default PARTITION OF measurements DEFAULT;
CREATE TABLE regions_list (id int, region text) PARTITION BY LIST (region);
CREATE TABLE regions_eu PARTITION OF regions_list FOR VALUES IN ('DE', 'FR', 'ES');
CREATE TABLE hash_part (id int) PARTITION BY HASH (id);
CREATE TABLE hash_part_0 PARTITION OF hash_part FOR VALUES WITH (MODULUS 4, REMAINDER 0);
CREATE INDEX idx_users_email ON users (email);
CREATE UNIQUE INDEX idx_users_lower_email ON users (lower(email));
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_orders_user_created ON orders (user_id, created_at DESC);
CREATE INDEX idx_orders_pending ON orders (created_at) WHERE status = 'pending';
CREATE INDEX idx_orders_cover ON orders (user_id) INCLUDE (total_cents, status);
CREATE INDEX idx_products_attrs ON products USING gin (attrs);
CREATE INDEX idx_products_attrs_path ON products USING gin (attrs jsonb_path_ops);
CREATE INDEX idx_products_tags ON products USING gin (tags);
CREATE INDEX idx_products_search ON products USING gist (search);
CREATE INDEX idx_events_brin ON events USING brin (created_at) WITH (pages_per_range = 32);
CREATE INDEX idx_nulls ON orders (shipped_at NULLS FIRST);
CREATE INDEX idx_hash ON sessions USING hash (token);
ALTER TABLE users ADD COLUMN last_login_at TIMESTAMPTZ;
ALTER TABLE users ADD COLUMN IF NOT EXISTS phone VARCHAR(32) NOT NULL DEFAULT '';
ALTER TABLE users DROP COLUMN IF EXISTS phone;
ALTER TABLE users ALTER COLUMN name SET NOT NULL;
ALTER TABLE users ALTER COLUMN name DROP NOT NULL;
ALTER TABLE users ALTER COLUMN role SET DEFAULT 'guest';
ALTER TABLE users ALTER COLUMN role DROP DEFAULT;
ALTER TABLE orders ALTER COLUMN total_cents TYPE BIGINT USING total_cents::bigint;
ALTER TABLE users RENAME COLUMN name TO full_name;
ALTER TABLE users RENAME TO app_users;
ALTER TABLE orders ADD CONSTRAINT orders_user_fk FOREIGN KEY (user_id) REFERENCES users (id) NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT orders_user_fk;
ALTER TABLE orders DROP CONSTRAINT IF EXISTS orders_user_fk;
ALTER TABLE orders ADD CONSTRAINT chk_total CHECK (total_cents >= 0);
ALTER TABLE orders ADD CONSTRAINT uq_orders UNIQUE (user_id, created_at);
ALTER TABLE orders ADD PRIMARY KEY (id);
ALTER TABLE orders ADD COLUMN a int, ADD COLUMN b int;
ALTER TABLE orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE measurements ATTACH PARTITION measurements_y2024m01 FOR VALUES FROM ('2024-01-01') TO ('2024-02-01');
ALTER TABLE measurements DETACH PARTITION measurements_y2024m01;
ALTER TABLE orders SET (fillfactor = 70);
ALTER TABLE orders OWNER TO app_owner;
ALTER INDEX idx_users_email RENAME TO idx_users_email_v2;
DROP INDEX CONCURRENTLY IF EXISTS idx_users_email_v2;
DROP TABLE IF EXISTS tmp_ids, staging_events CASCADE;
DROP TABLE audit_log;
TRUNCATE TABLE sessions, tokens RESTART IDENTITY CASCADE;
CREATE VIEW active_users AS SELECT id, email FROM users WHERE deleted_at IS NULL;
CREATE OR REPLACE VIEW order_totals AS SELECT user_id, SUM(total_cents) AS total FROM orders GROUP BY user_id;
CREATE MATERIALIZED VIEW daily_revenue AS SELECT date_trunc('day', created_at) AS day, SUM(total_cents) AS revenue FROM orders GROUP BY 1 WITH DATA;
CREATE UNIQUE INDEX idx_daily_revenue_day ON daily_revenue (day);
REFRESH MATERIALIZED VIEW CONCURRENTLY daily_revenue;
CREATE SEQUENCE order_seq START WITH 1000 INCREMENT BY 1 CACHE 10;
CREATE SCHEMA IF NOT EXISTS analytics;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TYPE mood AS ENUM ('sad', 'ok', 'happy');
CREATE DOMAIN positive_int AS integer CHECK (VALUE > 0);
COMMENT ON TABLE users IS 'Application users';
COMMENT ON COLUMN users.email IS 'Login email';
